import itertools

def R(g, mode='R'):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    # detect orientation: horizontal bars (many 8s per row) vs vertical
    rowcnt=sum(r.count(8) for r in g)
    colcnt=sum(r.count(8) for r in zip(*g))
    horiz = rowcnt>=colcnt
    twos=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    assert len(twos)==1, (twos)
    mr,mc=twos[0]
    cells={(r,c) for r in range(H) for c in range(W) if g[r][c]==8}

    if horiz:
        # bars = rows that are mostly 8
        bars=sorted({r for r in range(H) if sum(1 for c in range(W) if (r,c) in cells)>=W*0.7})
        gaps={}
        for b in bars:
            gaps[b]=[c for c in range(W) if (b,c) not in cells]
        # vertical connectors: from each gap cell, grow up (stop at mr or 8) and down (to 8 or bottom)
        for (br,gc) in [(b,c) for b in bars for c in gaps[b]]:
            # up
            r=br-1
            while r>=0 and r!=mr:
                if (r,gc) in cells: break
                out[r][gc]=2; r-=1
            r=br+1
            while r<H and (r,gc) not in cells:
                out[r][gc]=2; r+=1
        # midline rows between consecutive bars: FULL width 2-line
        for a,bp in zip(bars,bars[1:]):
            r=(a+bp)//2
            for c in range(W): out[r][c]=2
        # gap-row lines: bar's gap row = br-1, span between min/max gap cols
        for b in bars:
            rg=b-1
            if rg<0: continue
            gs=gaps[b]
            if len(gs)>1:
                for c in range(min(gs),max(gs)+1): out[rg][c]=2
            elif len(gs)==1:
                c=gs[0]; L=c-1; R=c+1
                # extend left to grid edge; right by 1 past gap col
                rr=L
                while rr>=0: out[rg][rr]=2; rr-=1
                rr=R+1
                while rr<W: out[rg][rr]=2; rr+=1
    else:
        bars=sorted({c for c in range(W) if sum(1 for r in range(H) if (r,c) in cells)>=H*0.7})
        gaps={b:[r for r in range(H) if (r,b) not in cells] for b in bars}
        mr,mc=twos[0]
        for (bc,gr) in [(b,r) for b in bars for r in gaps[b]]:
            c=bc
            for r in range(gr-1,-1,-1):
                if r==mr: break
                if (r,c) in cells: break
                out[r][c]=2
            for r in range(gr+1,H):
                if (r,c) in cells: break
                out[r][c]=2
        for a,bp in zip(bars,bars[1:]):
            c=(a+bp)//2
            for r in range(H): out[r][c]=2
        for b in bars:
            gr=gaps[b][0] if gaps[b] else None
            if gr is None: continue
            c=bc:=b
            for r in range(max(gr,0)-1,-1,-1):
                out[r][c]=2
            for r in range(min(gr,H)-1):
                out[r][c]=2
    return out

