from collections import Counter
def predict(a,radius=1,mode='majority',tie=None):
    H,W=a.shape
    o=np.zeros_like(a)
    for i in range(H):
        for j in range(W):
            y,x=i,j
            while True:
                vals=a[max(0,y-radius):min(H,y+radius+1), max(0,x-radius):min(W,x+radius+1)]
                c=Counter(vals.flatten().tolist())
                best,count=c.most_common(1)[0][1]
                cand={k:v for k,v in c.items() if v==best}
                if len(cand)==1: y-=radius; x-=radius; break
                radius+=1
            # count how many cells equal candidate within final window
            wv=a[max(0,y-radius):min(H,y+radius+1), max(0,x-radius):min(W,x+radius+1)]
            c=Counter(wv.flatten().tolist()); best=c.most_common(1)[0][0]
            o[y,x]=best
    return o
