def f(a,bg=None):
    if bg is None:
        vals,_=np.unique(np.ravel(a),return_counts=True)
        bg=int(vals[np.argmax(counts)])
    H,W=a.shape; o=np.full_like(a,bg)
    def near(i,j,d):
        y,x=i+d,j
        while 0<=y<H and 0<=x<W and a[y,x]==bg: y+=d; x+=d
        return a[y,x] if (0<=y<H and 0<=x<W) else None
    for i in range(H):
        for j in range(W):
            if a[i,j]!=bg: continue
            cands=[]
            for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                v=near(i,j,dy); xv,nx=x,y
                while 0<=v<nx+W and 0<=v+dx<H:
                    pass
                v=near(i,j,dy)
                u=near(i,j,dx)
            # collect nearest non-bg in all 4 dirs
            for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                v=near(i,j,dy*1); n=v
                # actually simpler: scan along ray
                y,x=i,j+dx
                while 0<=y<H and 0<=x<W and a[y,x]==bg: y+=dy; x+=dx
                cands.append((a[y,x], abs(dy)+abs(dx)))
            if not cands: continue
            best=min(cands)[0]
            cnt=Counter(v for v,r in cands if v==best)
            others={k:r for k,r in cands}
            if cnt>=2 or len(cands)<2:
                o[i,j]=best
            else:
                other=max((k for k in others.keys() if k!=best),key=lambda k:-others[k])
                o[i,j]=other if cnt<=len(cands)-cnt else best
    return o
