# Find shift: which single cyclic translation maps a->b? try shifts
for dr,dc in [(s,0) for s in range(H)]+[(0,s) for s in range(W)]:
    pred=[[a[(r-dr)%H][(c-dc)%W] for c in range(W)] for r in range(H)]
    if pred==b: print('match shift',dr,dc)
    if sum(1 for r in range(H) for c in range(W) if pred[r][c]!=b[r][c])<200: print('near',dr,dc,sum(1 for r in range(H) for c in range(W) if pred[r][c]!=b[r][c]))

